--preconditions onFail:MARK_RAN onError:HALT
--precondition-sql-check expectedResult:0 SELECT count() FROM system.tables WHERE database = 'analytics' AND name = 'mv_vendor_types'
CREATE MATERIALIZED VIEW IF NOT EXISTS analytics.mv_vendor_types ON CLUSTER '{cluster}' TO analytics.vendor_types (`product` LowCardinality(String), `tenant` LowCardinality(String), `vendor_type_id` Int32, `name` String, `description` Nullable(String), `is_active` Bool, `created_on` DateTime64(3), `created_by` String, `last_modified_on` Nullable(DateTime64(3)), `last_modified_by` Nullable(String), `eligible_for_sign_up` Bool, `only_use_selected_order_types` Bool, `only_use_selected_qualification_groups` Bool, `auto_complete_order_on_file_submission` Bool, `selected_loan_type_ids` Nullable(String), `is_selected_loan_type` Bool, `restrict_auto_completion_for_nonagency_orders` Bool, `_version` UInt64, `_deleted` UInt8) AS SELECT _product AS product, _tenant AS tenant, Vendor_Type_ID AS vendor_type_id, Vendor_Type_Name AS name, Vendor_Type_Description AS description, Is_Active AS is_active, Created_On AS created_on, Created_By AS created_by, Last_Modified_On AS last_modified_on, Last_Modified_By AS last_modified_by, Eligible_For_Sign_Up AS eligible_for_sign_up, Only_Use_Selected_Order_Types AS only_use_selected_order_types, Only_Use_Selected_Qualification_Groups AS only_use_selected_qualification_groups, Auto_Complete_Order_On_File_Submission AS auto_complete_order_on_file_submission, Selected_Loan_Type_IDs AS selected_loan_type_ids, Is_Selected_Loan_Type AS is_selected_loan_type, Restrict_Auto_Completion_For_NonAgency_Orders AS restrict_auto_completion_for_nonagency_orders, _source_ts_ms AS _version, toUInt8(__deleted = 'true') AS _deleted FROM raw.vendor_types;
--rollback DROP VIEW IF EXISTS analytics.mv_vendor_types ON CLUSTER '{cluster}' SYNC;